        /// <param name="cancellationToken">Cancellation Token to cancel the request.</param>
        /// <returns>Task of GetBrandsResponse</returns>
        System.Threading.Tasks.Task<GetBrandsResponse> GetBrandsAsync(long pageSize, string? categoryId = default, bool? isAuthorized = default, string? brandName = default, string? pageToken = default, string? categoryVersion = default, System.Threading.CancellationToken cancellationToken = default);

